  async function uploadMedia(file,bucket,allowed,maxBytes){if(!file?.size)return null;if(!allowed.includes(file.type))throw Error('Choose a supported file type.');if(file.size>maxBytes)throw Error(`File must be smaller than ${Math.round(maxBytes/1048576)} MB.`);const ext=(file.name.split('.').pop()||'bin').toLowerCase().replace(/[^a-z0-9]/g,'');const objectPath=`${session.user.id}/${crypto.randomUUID()}.${ext}`;const uploaded=await client.storage.from(bucket).upload(objectPath,file,{contentType:file.type,upsert:false});if(uploaded.error)throw uploaded.error;return objectPath}
