  async function adminOutreach(){const ev=await client.from('events').select('id,title,starts_at').order('starts_at',{ascending:false});const sel=$('[data-outreach-event]');sel.innerHTML='<option value="">Select an event</option>'+ev.data.map(e=>`<option value="${e.id}">${esc(e.title)} — ${date(e.starts_at)}</option>`).join('');let rows=[];$('[data-outreach-form]').onsubmit=async e=>{e.preventDefault();const r=await client.rpc('admin_attendee_contacts',{target_event:sel.value});if(r.error)return msg(r.error.message,true);rows=r.data||[];$('[data-outreach-results]').innerHTML=rows.map(x=>`<tr><td>${esc(x.membership_number)}</td><td>${esc(x.first_name)} ${esc(x.last_name)}</td><td>${esc(x.email)}</td><td>${x.communication_consent?'Yes':'No'}</td></tr>`).join('');$('[data-copy-emails]').disabled=!rows.length;$('[data-export-attendance]').disabled=!rows.length};$('[data-copy-emails]').onclick=()=>navigator.clipboard.writeText(rows.filter(x=>x.communication_consent).map(x=>x.email).join('; ')).then(()=>msg('Consenting attendee emails copied for BCC.'));$('[data-export-attendance]').onclick=()=>downloadCsv('attendance.csv',[['Member','First name','Last name','Email','Consent'],...rows.map(x=>[x.membership_number,x.first_name,x.last_name,x.email,x.communication_consent?'yes':'no'])])}
