  async function adminPoints(){const [r,bank,members]=await Promise.all([client.from('point_transactions').select('created_at,amount,reason,members(membership_number)').order('created_at',{ascending:false}).limit(200),client.rpc('admin_point_bank_balance'),client.rpc('admin_member_directory')]);if(bank.error)throw bank.error;const balance=$('[data-point-bank]');if(balance)balance.textContent=Number(bank.data).toLocaleString();$('[data-admin-points]').innerHTML=(r.data||[]).map(x=>`<tr><td>${date(x.created_at)}</td><td>${esc(x.members?.membership_number)}</td><td>${money(x.amount)}</td><td>${esc(x.reason)}</td></tr>`).join('');const select=$('[data-point-member]');if(select)select.innerHTML='<option value="">Select a member</option>'+(members.data||[]).filter(x=>x.membership_status==='active').map(x=>`<option value="${x.membership_id}">${esc(x.first_name)} ${esc(x.last_name)} · ${esc(x.membership_number)}</option>`).join('');$('[data-quick-point-form]')?.addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(e.currentTarget),result=await client.rpc('admin_award_points_from_bank',{target_member:d.get('member'),points:Number(d.get('amount')),award_reason:d.get('reason')});msg(result.error?result.error.message:`Points awarded. ${result.data} remain in your bank.`,!!result.error);if(!result.error)location.reload()})}

